private let sqliteTransient = unsafeBitCast(-1, to: sqlite3_destructor_type.self)

public enum LunaVaultSearchModule { public static let identifier = "LunaVaultSearch" }

public struct VaultSearchConfiguration: Equatable, Sendable {
    public let maximumResults: Int
    public init(maximumResults: Int = 50) { self.maximumResults = max(1, maximumResults) }
}

public enum VaultDocumentSource: String, Codable, CaseIterable, Sendable { case device, iCloud, mac }

public struct VaultIndexedDocument: Equatable, Sendable {
    public let id: VaultObjectID; public let revision: UUID; public let filename: String
    public let bodyText: String; public let ocrText: String; public let transcriptText: String
    public let createdAt: Date; public let updatedAt: Date; public let accessedAt: Date
    public let source: VaultDocumentSource; public let embedding: VaultEmbedding?; public let isTombstone: Bool
    public init(id: VaultObjectID, revision: UUID, filename: String, bodyText: String = "", ocrText: String = "", transcriptText: String = "", createdAt: Date, updatedAt: Date, accessedAt: Date, source: VaultDocumentSource = .device, embedding: VaultEmbedding? = nil, isTombstone: Bool = false) {
        self.id=id; self.revision=revision; self.filename=filename; self.bodyText=bodyText; self.ocrText=ocrText; self.transcriptText=transcriptText; self.createdAt=createdAt; self.updatedAt=updatedAt; self.accessedAt=accessedAt; self.source=source; self.embedding=embedding; self.isTombstone=isTombstone
    }
}

public struct VaultSearchHit: Equatable, Sendable {
    public let objectID: VaultObjectID; public let canonicalObjectID: VaultObjectID; public let filename: String; public let snippet: String; public let score: Double
    public let createdAt: Date; public let updatedAt: Date; public let accessedAt: Date; public let source: VaultDocumentSource; public let matchedFields: [String]; public let isSymbolicAlias: Bool
    public init(objectID: VaultObjectID, canonicalObjectID: VaultObjectID, filename: String, snippet: String, score: Double, createdAt: Date, updatedAt: Date, accessedAt: Date, source: VaultDocumentSource, matchedFields: [String] = [], isSymbolicAlias: Bool = false) { self.objectID=objectID; self.canonicalObjectID=canonicalObjectID; self.filename=filename; self.snippet=snippet; self.score=score; self.createdAt=createdAt; self.updatedAt=updatedAt; self.accessedAt=accessedAt; self.source=source; self.matchedFields=matchedFields; self.isSymbolicAlias=isSymbolicAlias }
}

public protocol VaultVectorIndex: Sendable { func cosineSearch(query: VaultEmbedding, limit: Int) throws -> [(VaultObjectID, Double)] }
public struct BruteForceVaultVectorIndex: VaultVectorIndex {
    private let search: @Sendable (VaultEmbedding, Int) throws -> [(VaultObjectID, Double)]
    public init(search: @escaping @Sendable (VaultEmbedding, Int) throws -> [(VaultObjectID, Double)]) { self.search=search }
    public func cosineSearch(query: VaultEmbedding, limit: Int) throws -> [(VaultObjectID, Double)] { try search(query, limit) }
}

public protocol VaultGroupNaming: Sendable { func name(for members: [VaultIndexedDocument]) -> String }
public struct KeywordVaultGroupNamer: VaultGroupNaming {
    public init() {}
    public func name(for members: [VaultIndexedDocument]) -> String { let stop:Set<String>=["the","and","for","with","from","this","that","file"]; var counts:[String:Int]=[:]; for member in members { for word in (member.filename+" "+member.bodyText).lowercased().split(whereSeparator: { !$0.isLetter && !$0.isNumber }).map(String.init) where word.count>2 && !stop.contains(word) { counts[word,default:0]+=1 } }; let words=counts.sorted{ $0.value == $1.value ? $0.key < $1.key : $0.value > $1.value }.prefix(3).map { $0.key }; return words.isEmpty ? "Untitled group" : words.map{$0.capitalized}.joined(separator:" · ") }
}

public struct VaultGroup: Equatable, Sendable { public let id:UUID; public var label:String; public var memberIDs:[VaultObjectID]; public var frozen:Bool; public let automatic:Bool; public let createdAt:Date; public var updatedAt:Date; public init(id:UUID,label:String,memberIDs:[VaultObjectID],frozen:Bool=false,automatic:Bool=true,createdAt:Date,updatedAt:Date){self.id=id;self.label=label;self.memberIDs=memberIDs;self.frozen=frozen;self.automatic=automatic;self.createdAt=createdAt;self.updatedAt=updatedAt} }
public struct VaultQueryGroup: Equatable, Sendable { public let id:UUID; public let query:String; public let memberIDs:[VaultObjectID]; public let live:Bool; public let createdAt:Date; public init(id:UUID,query:String,memberIDs:[VaultObjectID],live:Bool,createdAt:Date){self.id=id;self.query=query;self.memberIDs=memberIDs;self.live=live;self.createdAt=createdAt} }
public struct VaultSymbolicAlias: Equatable, Sendable { public let id: UUID; public let originalObjectID: VaultObjectID; public let groupID: UUID; public let modelVersion: String; public let embedding: VaultEmbedding; public init(id: UUID, originalObjectID: VaultObjectID, groupID: UUID, embedding: VaultEmbedding) { self.id=id; self.originalObjectID=originalObjectID; self.groupID=groupID; self.modelVersion=embedding.modelVersion; self.embedding=embedding } }

public enum VaultSearchError: Error, Equatable, Sendable { case sqlite(String); case invalidQuery; case mixedModelSpace; case dimensionMismatch(expected:Int,actual:Int); case missingDocument }

